@import "tailwindcss";
@import "tw-animate-css";
@import "shadcn/tailwind.css";
@import "@fontsource-variable/geist";

@custom-variant dark (&:is(.dark *));

@theme inline {
    /* Design Tokens: Agentrack Design System */

    /* Typography */
    --agentrack-font-sans: 'Geist Variable', sans-serif;
    --agentrack-font-heading: var(--agentrack-font-sans);
    --agentrack-font-size-xs: 0.75rem;
    --agentrack-font-size-sm: 0.875rem;
    --agentrack-font-size-base: 1rem;
    --agentrack-font-size-lg: 1.125rem;
    --agentrack-font-size-xl: 1.25rem;
    --agentrack-font-size-2xl: 1.5rem;
    --agentrack-font-size-3xl: 1.875rem;
    --agentrack-font-weight-normal: 400;
    --agentrack-font-weight-medium: 500;
    --agentrack-font-weight-semibold: 600;
    --agentrack-font-weight-bold: 700;
    --agentrack-line-height-tight: 1.25;
    --agentrack-line-height-normal: 1.5;
    --agentrack-line-height-relaxed: 1.625;

    /* Spacing System */
    --agentrack-spacing-0: 0rem;
    --agentrack-spacing-0_5: 0.125rem;
    --agentrack-spacing-1: 0.25rem;
    --agentrack-spacing-1_5: 0.375rem;
    --agentrack-spacing-2: 0.5rem;
    --agentrack-spacing-3: 0.75rem;
    --agentrack-spacing-4: 1rem;
    --agentrack-spacing-5: 1.25rem;
    --agentrack-spacing-6: 1.5rem;
    --agentrack-spacing-8: 2rem;
    --agentrack-spacing-10: 2.5rem;
    --agentrack-spacing-12: 3rem;
    --agentrack-spacing-16: 4rem;

    /* Colors - Status */
    --agentrack-color-status-todo: oklch(0.87 0 0);
    --agentrack-color-status-in-progress: oklch(0.8 0.1 40);
    --agentrack-color-status-done: oklch(0.7 0.15 130);
    --agentrack-color-status-closed: oklch(0.65 0.2 20);
    --agentrack-color-status-idea: oklch(0.6 0.15 280);

    /* Colors - Priority */
    --agentrack-color-priority-p1: oklch(0.577 0.245 27.325); /* Critical - Red */
    --agentrack-color-priority-p2: oklch(0.7 0.2 35); /* High - Orange */
    --agentrack-color-priority-p3: oklch(0.75 0.15 50); /* Medium - Yellow */
    --agentrack-color-priority-p4: oklch(0.8 0.1 70); /* Low - Lime */
    --agentrack-color-priority-p5: oklch(0.85 0.05 90); /* None - Gray */

    /* Colors - Semantic */
    --agentrack-color-success: oklch(0.7 0.15 130);
    --agentrack-color-warning: oklch(0.8 0.1 40);
    --agentrack-color-error: oklch(0.577 0.245 27.325);
    --agentrack-color-info: oklch(0.6 0.15 280);

    /* Colors - Neutral Palette */
    --agentrack-color-neutral-50: oklch(0.99 0 0);
    --agentrack-color-neutral-100: oklch(0.97 0 0);
    --agentrack-color-neutral-200: oklch(0.95 0 0);
    --agentrack-color-neutral-300: oklch(0.9 0 0);
    --agentrack-color-neutral-400: oklch(0.85 0 0);
    --agentrack-color-neutral-500: oklch(0.8 0 0);
    --agentrack-color-neutral-600: oklch(0.7 0 0);
    --agentrack-color-neutral-700: oklch(0.6 0 0);
    --agentrack-color-neutral-800: oklch(0.5 0 0);
    --agentrack-color-neutral-900: oklch(0.4 0 0);

    /* Colors - Brand/Accent */
    --agentrack-color-brand-primary: oklch(0.205 0 0);
    --agentrack-color-brand-primary-foreground: oklch(0.985 0 0);

    /* Design Utilities */
    --agentrack-border-radius-sm: 0.25rem;
    --agentrack-border-radius-md: 0.375rem;
    --agentrack-border-radius-lg: 0.5rem;
    --agentrack-border-radius-xl: 0.75rem;
    --agentrack-border-radius-full: 9999px;

    --agentrack-shadow-sm: 0 1px 2px 0 rgb(0 0 0 / 0.05);
    --agentrack-shadow-md: 0 4px 6px -1px rgb(0 0 0 / 0.1);
    --agentrack-shadow-lg: 0 10px 15px -3px rgb(0 0 0 / 0.1);

    --agentrack-transition-duration-fast: 100ms;
    --agentrack-transition-duration-normal: 200ms;
    --agentrack-transition-duration-slow: 300ms;

    --agentrack-z-index-dropdown: 1000;
    --agentrack-z-index-sticky: 1020;
    --agentrack-z-index-fixed: 1030;
    --agentrack-z-index-modal: 1040;
    --agentrack-z-index-popover: 1050;
    --agentrack-z-index-toast: 1060;
    --agentrack-z-index-overlay: 1070;

    /* Existing shadcn variables */
    --font-heading: var(--agentrack-font-sans);
    --font-sans: 'Geist Variable', sans-serif;
    --color-sidebar-ring: var(--sidebar-ring);
    --color-sidebar-border: var(--sidebar-border);
    --color-sidebar-accent-foreground: var(--sidebar-accent-foreground);
    --color-sidebar-accent: var(--sidebar-accent);
    --color-sidebar-primary-foreground: var(--sidebar-primary-foreground);
    --color-sidebar-primary: var(--sidebar-primary);
    --color-sidebar-foreground: var(--sidebar-foreground);
    --color-sidebar: var(--sidebar);
    --color-chart-5: var(--chart-5);
    --color-chart-4: var(--chart-4);
    --color-chart-3: var(--chart-3);
    --color-chart-2: var(--chart-2);
    --color-chart-1: var(--chart-1);
    --color-ring: var(--ring);
    --color-input: var(--input);
    --color-border: var(--border);
    --color-destructive: var(--destructive);
    --color-accent-foreground: var(--accent-foreground);
    --color-accent: var(--accent);
    --color-muted-foreground: var(--muted-foreground);
    --color-muted: var(--muted);
    --color-secondary-foreground: var(--secondary-foreground);
    --color-secondary: var(--secondary);
    --color-primary-foreground: var(--primary-foreground);
    --color-primary: var(--primary);
    --color-popover-foreground: var(--popover-foreground);
    --color-popover: var(--popover);
    --color-card-foreground: var(--card-foreground);
    --color-card: var(--card);
    --color-foreground: var(--foreground);
    --color-background: var(--background);
    --radius-sm: calc(var(--radius) * 0.6);
    --radius-md: calc(var(--radius) * 0.8);
    --radius-lg: var(--radius);
    --radius-xl: calc(var(--radius) * 1.4);
    --radius-2xl: calc(var(--radius) * 1.8);
    --radius-3xl: calc(var(--radius) * 2.2);
    --radius-4xl: calc(var(--radius) * 2.6);
}

:root {
    /* Design Tokens: Agentrack Design System - Light Mode */

    /* Backgrounds & Foregrounds */
    --background: oklch(1 0 0);
    --foreground: oklch(0.145 0 0);
    --card: oklch(1 0 0);
    --card-foreground: oklch(0.145 0 0);
    --popover: oklch(1 0 0);
    --popover-foreground: oklch(0.145 0 0);

    /* Primary Colors */
    --primary: oklch(0.205 0 0);
    --primary-foreground: oklch(0.985 0 0);
    --secondary: oklch(0.97 0 0);
    --secondary-foreground: oklch(0.205 0 0);
    --accent: oklch(0.97 0 0);
    --accent-foreground: oklch(0.205 0 0);

