import { cn } from "@/lib/utils";
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from "@/components/ui/tooltip";

const priorityConfig: Record<number, {
  label: string;
  color: string;
  ariaLabel: string;
}> = {
  1: {
    label: "P1",
