    color: "var(--agentrack-color-priority-p5)",
    ariaLabel: "None"
  },
};

interface PriorityIndicatorProps {
  priority: number;
  className?: string;
}

export function PriorityIndicator({ priority, className }: PriorityIndicatorProps) {
